function expectedHits(N,K,n,max){n=Math.min(n,N);if(!N||!K||!n)return 0;let e=0;const all=choose(N,n);for(let x=1;x<=Math.min(K,n);x++)e+=Math.min(x,max)*choose(K,x)*choose(N-K,n-x)/all;return e;}
