 <div class="records-actions"><button id="records-export">戦績JSONを書き出す</button><label class="file">戦績JSONを読み込む<input id="records-import" type="file" accept="application/json,.json"></label><button id="records-pending-export">未保存分だけ書き出す</button><button id="records-retry">未保存分を再保存</button><button id="records-damaged">保存原本を書き出す</button><button id="records-recover">直前のバックアップに復旧</button></div><p>読み込みは重複を除いて追加。同じIDで結果が異なる場合は全体を拒否します。マイデッキ自体の移行はマイデッキ画面から行います。実績・報酬・カード解放には影響しません。</p></details>`;
 const $=id=>document.getElementById(id);let tab=0,scope='cpu',query='',page=0,origin;
 const status=m=>$('records-status').textContent=m;
 function data(){try{store.refresh();}catch(e){status('保存を読み込めません：'+e.message);}return summarize(store.records,{scope});}
 function cardRows(s){const q=query.trim().toLowerCase();const all=Object.values(CARDS).filter(c=>!q||`${c.name} ${c.id}`.toLowerCase().includes(q)).sort((a,b)=>s.cards[b.id].uses-s.cards[a.id].uses||a.name.localeCompare(b.name));const shown=all.slice(page*24,(page+1)*24);
 return `<p>全452種類 · 該当${all.length}種類。使用回数順。${Object.values(s.cards).filter(t=>t.uses>0).length}/452種類を使用。</p><p>勝率はデッキ・相手・先後にも左右されます。カードの強さの判定ではありません。</p><label>カード名・ID<input id="records-query" type="search" value="${h(query)}" placeholder="カードを探す"></label><div class="records-card-list">${shown.map(c=>{const t=s.cards[c.id];return `<article><button type="button" class="records-card-art" data-record-card="${h(c.id)}" aria-label="${h(c.name)}の詳細">${cardMarkup(c,{compact:true})}</button><div><h3>${h(c.name)}</h3><p>採用 ${t.copies}枚 / ${t.total}戦 · 採用時勝率 ${winRate(t)}</p><p>使用 ${t.uses}回 / ${t.usedMatches}戦 · 使用時勝率 ${winRate({total:t.usedMatches,wins:t.usedWins})}</p><small>${t.total<10?'採用10戦未満 · 参考値':''} ${t.usedMatches<10?'使用10戦未満 · 参考値':''}</small></div></article>`;}).join('')}</div><div class="records-actions"><button data-record-page="-1" ${page===0?'disabled':''}>前へ</button><span>${page+1}/${Math.max(1,Math.ceil(all.length/24))}</span><button data-record-page="1" ${(page+1)*24>=all.length?'disabled':''}>次へ</button></div>`;}
 function render(){const s=data();$('records-scope-wrap').hidden=![2,4].includes(tab);for(const b of d.querySelectorAll('[data-record-tab]'))b.setAttribute('aria-pressed',String(Number(b.dataset.recordTab)===tab));
 if(store.error)status(store.error+'。原本を書き出して保護し、バックアップ復旧を選べます。');else if(store.pending.length)status('未保存の戦績があります。JSON書き出しまたは再保存をしてください。');
 const body=$('records-body');if(tab===0)body.innerHTML=`<h3>総合戦績</h3><p>この端末の決着済み対戦：<strong>${s.total}</strong>戦</p><article><h3>CPU対戦 · 自分の戦績</h3><p>${counts(s.cpu)}</p></article><article><h3>同じ端末で2人対戦 · ${s.hotseat.total}戦</h3><p>A席 ${counts(s.hotseat.A)}</p><p>B席 ${counts(s.hotseat.B)}</p><small>個人のCPU勝率には含めません。</small></article><p>オンライン対戦は未対応です。別の対戦モードとして扱います。</p>${s.total?'':'<p>まだ戦績はありません。通常対戦が決着すると自動で記録されます。</p>'}`;
 if(tab===1)body.innerHTML=`<h3>CPUの強さ別</h3><p>初級 ${counts(s.difficulty.beginner)}</p><p>中級 ${counts(s.difficulty.intermediate)}</p><h3>相手の戦略デッキ別</h3>${CPU_DECKS.map(c=>`<article><h4>${h(c.name)}</h4><p>${counts(s.opponents[c.id])}</p></article>`).join('')}<p>CPUがマイデッキを使用した対戦は難易度別のみへ集計します。</p>`;
 if(tab===2){const current=new Map(listDecks().map(x=>[x.id,x]));const list=new Map([...current].map(([id,x])=>[id,{...{total:0,wins:0,losses:0,draws:0,lastUsed:null,versions:{}},name:x.name}]));for(const [id,t] of Object.entries(s.decks))list.set(id,t);body.innerHTML=`<h3>マイデッキ別</h3><p>同じIDの成績をまとめ、対戦時の構成ごとにも分けて表示します。</p>${[...list].map(([id,t])=>`<article><h4>${h(current.get(id)?.name??t.name)} ${current.has(id)?'':'（過去のデッキ）'}</h4><p>${counts(t)}</p><p>最終使用：${t.lastUsed===null?'記録なし':date(t.lastUsed)}</p>${Object.values(t.versions).map((v,i)=>`<details><summary>構成${i+1} · ${counts(v)}</summary><p>${h(names(v.cards))}</p></details>`).join('')}</article>`).join('')||'<p>まだデッキ別成績はありません。</p>'}`;}
 if(tab===3){const rows=[...store.records].sort((a,b)=>(b.endedAt??0)-(a.endedAt??0)||a.id.localeCompare(b.id)).slice(0,HISTORY_LIMIT);body.innerHTML=`<h3>最近の対戦履歴</h3><p>直近${rows.length}戦 / 累計${store.records.length}戦</p>${rows.map(r=>`<details><summary>${date(r.endedAt)} · ${r.mode==='cpu'?labels[resultFor(r,r.human)]:r.winner?r.winner+'席の勝利':'引き分け'}</summary><p>${r.mode==='cpu'?`CPU ${r.difficulty==='beginner'?'初級':'中級'} · 自分${r.human}（${r.human==='A'?'先攻':'後攻'}）`:'2人対戦 · A先攻/B後攻'}</p><p>決着 R${r.round} · そだち A ${r.growth.A} / B ${r.growth.B}</p>${['A','B'].map(seat=>`<p>${seat}：${h(r.decks[seat].name)}</p><details><summary>対戦時の40枚</summary><p>${h(names(r.decks[seat].cards))}</p></details>`).join('')}<p>CPU戦略：${h(CPU_DECKS.find(c=>c.id===r.cpuDeck)?.name??'指定なし')}</p><small>対戦ID ${h(r.id)}</small></details>`).join('')||'<p>決着した対戦はまだありません。</p>'}`;}
 if(tab===4)body.innerHTML=cardRows(s);
 }
 d.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.recordTab!==undefined){tab=Number(b.dataset.recordTab);page=0;render();}if(b.dataset.recordPage){page+=Number(b.dataset.recordPage);render();$('records-body').scrollIntoView?.({block:'start'});}if(b.dataset.recordCard)inspect(b.dataset.recordCard,{catalog:true,origin:b});});
 $('records-body').addEventListener('input',e=>{if(e.target.id==='records-query'){query=e.target.value;page=0;const pos=e.target.selectionStart;render();$('records-query').focus();try{$('records-query').setSelectionRange(pos,pos);}catch{}}});
 $('records-scope').onchange=e=>{scope=e.target.value;page=0;render();};
 $('records-close').onclick=()=>d.close();d.addEventListener('close',()=>{origin?.focus?.();onClose();});
 $('records-export').onclick=()=>{try{download(store.exportJSON(),'naotocchi-card-records.json');status('戦績JSONを書き出しました（未保存分も含みます）。');}catch(e){status(e.message);}};
 $('records-pending-export').onclick=()=>{try{download(store.exportPendingJSON(),'naotocchi-records-unsaved.json');status('未保存分だけを書き出しました。保存済み分は通常の戦績JSONから書き出せます。');}catch(e){status(e.message);}};
 $('records-damaged').onclick=()=>{try{download(store.exportDamaged(),'naotocchi-records-original.json');status('保存原本を書き出しました。');}catch(e){status(e.message);}};
 $('records-import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>MAX_BYTES)throw Error('8MB以内のJSONを選んでください');const raw=await file.text();await withLock(()=>store.importJSON(raw));render();status('戦績を検証して追加しました。重複は加算していません。');}catch(err){status('読み込みを拒否しました：'+err.message);}finally{e.target.value='';}};
 $('records-retry').onclick=async()=>{try{await withLock(()=>store.write([]));render();status('保存できました。');}catch(e){status('保存できません：'+e.message);}};
 $('records-recover').onclick=async()=>{if(!confirm('直前のバックアップへ戻します。現在の原本を先に書き出して保護してください。復旧しますか？'))return;try{await withLock(()=>store.recover());render();status('直前のバックアップから復旧しました。');}catch(e){status('復旧できません：'+e.message);}};
 return {open:(source,cardId=null)=>{origin=source;if(cardId){tab=4;query=cardId;page=0;}onOpen();render();if(!d.open)d.showModal();$('records-close').focus();},refresh:()=>{if(d.open)render();}};
}

