export const other=a=>a==='A'?'B':'A';
export const card=(s,id)=>id?CATALOG[s.cards[id].cardId]:null;
export const owner=(s,a)=>s.players[a];
export const board=(s,a)=>owner(s,a).board;
export const main=(s,a)=>card(s,board(s,a).main);
export const countBoard=(s,a)=>{const b=board(s,a);return [b.main,b.partner,b.world].filter(Boolean).length+b.companions.length+b.prepared.length;};
export const played=(s,a,type)=>s.history.filter(e=>e.serial===s.serial&&e.actor===a&&e.kind==='play'&&(!type||e.type===type&&(type!=='play'||e.faceUp)));
export const draw=(n=1,to='self')=>({op:'draw',n,to});
export const growth=(n,to='self')=>({op:'growth',n,to});
export const search=(n,filter={},max=1,optional=false,reveal=false)=>({op:'search',n,filter,max,min:optional?0:1,reveal});
export const stat=(power=0,wisdom=0,duration='turn')=>({op:'stat',power,wisdom,duration});
export const move=(destination='hand')=>({op:'move',destination});
export const iff=(condition,steps)=>({op:'if',condition,steps});
export function add(id,rule){if(!CATALOG[id])throw Error('Unknown source '+id);RULES[id]=rule;}
export function supported(id){return !!BASE[id]||!!RULES[id];}
