 s=doAction(s,find(s,a=>a.kind==='pass'));s=settle(s);
 assert.notEqual(s.turn,'A');assert.equal(djReservations(s).length,0);assert.equal(s.players.A.growth,growth);assert.equal(s.players.A.hand.length,handBefore);
