  :hidden?'<p class="stage-note">相手の伏せ札は確認できません。</p>'
  :readOnly&&actions.length?`<div class="stage-actions actions"><button type="button" data-inspect="${h(c.id)}"><span class="action-main">このカードの操作を開く</span></button></div>`:'';
 return `<header class="detail-toolbar"><span>${catalog?'カード図鑑':readOnly?'カード閲覧':h(turnStatus(v))}</span><button type="button" class="stage-zoom inspection-control" data-stage-zoom aria-pressed="false">拡大</button><button type="button" class="dialog-close" data-close>閉じる ×</button></header><div class="card-stage"><div class="stage-scroll"><div class="stage-card" data-stage-zoom role="button" tabindex="0" aria-label="${h(hidden?'非公開のカード':c.name)}・ダブルタップで拡大／縮小"><div class="stage-card-canvas">${cardMarkup(c,{detail:true})}</div></div></div>${band?`<section class="stage-band">${band}</section>`:''}</div>`;
